--   -- expect 12 rows, 1..12, the four new slugs at 9-12.
-- Rollback: DELETE FROM public.grammar_exercises/grammar_examples/grammar_rules
-- WHERE topic_id IN (SELECT id FROM public.grammar_topics WHERE slug IN ('stem-changing-verbs', 'imperative', 'perfekt-intro', 'dative-prepositions-intro') AND sub_level = 'A1.2');
-- then DELETE FROM public.grammar_topics WHERE slug IN (...) AND sub_level = 'A1.2';
-- the CHECK stays at 1..12 regardless (still needed by A1.1).
-- Idempotent: every INSERT is guarded by WHERE NOT EXISTS (id); the ALTER
