INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'A1.2', 9, 'Stem-Changing Verbs (e→i, e→ie, a→ä, au→äu)', 'Verben mit Vokalwechsel (e→i, e→ie, a→ä, au→äu)', 'stem-changing-verbs', 'Learn 15 verbs that change their stem vowel for du and er/sie/es: sprechen, essen, fahren, lesen, nehmen, laufen and more. All other forms — ich, wir, ihr, sie/Sie — stay regular.', 'Lerne 15 Verben mit Vokalwechsel bei du und er/sie/es. Alle anderen Formen bleiben regelmäßig.', 20, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['present-tense-regular','separable-verbs-intro']::text[], ARRAY['imperative']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid);

INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT 'ba627722-82e9-5c38-a8f4-3b5913b7b4a4'::uuid, 'A1.2', 10, 'Imperative (Commands & Requests)', 'Imperativ: Befehle und Bitten', 'imperative', 'Learn the du/ihr/Sie imperative for polite requests — Sprechen Teil 3 Bitten and Hören Teil 3 announcements. Covers stem-changing du-forms (Nimm!, Sprich!) and separable verbs (Mach das Fenster auf!). A2.1 imperative-mood goes deeper with more verbs and contexts.', 'Lerne den du/ihr/Sie-Imperativ für Bitten: Sprechen Teil 3 und Hören-Ansagen. Dazu lernst du Vokalwechsel (Nimm!, Sprich!) und trennbare Verben. A2.1 Imperativ vertieft das Thema mit mehr Verben.', 20, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['present-tense-regular','separable-verbs-intro','stem-changing-verbs']::text[], ARRAY['modal-verbs-intro']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = 'ba627722-82e9-5c38-a8f4-3b5913b7b4a4'::uuid);

