SELECT '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'A1.2', 11, 'Perfekt: What Happened Yesterday', 'Das Perfekt', 'perfekt-intro', 'Learn the Perfekt tense with haben or sein plus Partizip II. Say what happened yesterday. Use war/hatte for sein and haben.', 'Lerne das Perfekt mit haben oder sein plus Partizip II. Was hast du gestern gemacht? Sag es im Perfekt. Für sein und haben nimmst du war und hatte.', 25, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['present-tense-regular','separable-verbs-intro','stem-changing-verbs']::text[], ARRAY['dative-prepositions-intro','basic-sentence-structure']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid);

