SELECT '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 'A1.2', 12, 'Dative prepositions: aus, bei, mit, nach, zu', 'Präpositionen mit Dativ: aus, bei, mit, nach, von, zu, seit', 'dative-prepositions-intro', 'Learn the seven prepositions that always take Dativ, the contractions zum/zur/beim/vom, and how to say where you come from, live and travel.', 'Lerne die sieben Präpositionen mit Dativ. Lerne auch die Kurzformen zum, zur, beim und vom.', 20, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['definite-articles','possessive-articles','prepositions-accusative']::text[], ARRAY['perfekt-intro','stem-changing-verbs']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid);

-- Rules
INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '69e2d1a2-1ad0-5d4a-95c2-87926b811019'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'introduction', 'Stem-Changing Verbs Introduction', 'Einführung: Verben mit Vokalwechsel', '{"hook_de":"Du sprichst Deutsch. Du isst gern Pizza. Du fährst mit dem Bus. Der Vokal wechselt!","hook_en":"Du sprichst Deutsch (you speak German). Du isst gern Pizza (you like eating pizza). Du fährst mit dem Bus (you go by bus). Notice the vowel change from the infinitive.","scenario_en":"Some common verbs change their stem vowel, but only for du and er/sie/es — every other form stays the regular pattern you already know.","preview_note_en":"sprechen → du sprichst, er spricht. Everyone else stays regular.","preview_highlight":"sprechen, du sprichst","why_it_matters_en":"These 15 verbs are on the A1 word list and appear in almost every reading text and Sprechen task.","preview_example_de":"Ich spreche Deutsch. Du sprichst Deutsch.","preview_example_en":"I speak German. You speak German.","german_difference_en":"English never changes the verb''s vowel for you: I speak, you speak. German changes the vowel only in du and er/sie/es: ich spreche, du sprichst, er spricht.","english_comparison_en":"English adds -s only for he/she/it (he speaks). German changes the vowel itself for du and er/sie/es, on top of the normal ending."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '69e2d1a2-1ad0-5d4a-95c2-87926b811019'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '7e280428-6b6e-5e08-a7a4-6aec7201ff44'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'table', 'e → i: sprechen, essen, nehmen', 'e → i: sprechen, essen, nehmen', '{"type":"case_table","headers":["Person","sprechen","essen","nehmen"],"rows":[["ich","spreche","esse","nehme"],["du","sprichst","isst","nimmst"],["er/sie/es","spricht","isst","nimmt"],["wir","sprechen","essen","nehmen"],["ihr","sprecht","esst","nehmt"],["sie/Sie","sprechen","essen","nehmen"]],"highlight_row":-1,"description_de":"e wird zu i bei du und er/sie/es. nehmen verdoppelt zusätzlich das m: nimmst, nimmt.","description_en":"e becomes i for du and er/sie/es. nehmen also doubles the m: nimmst, nimmt."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '7e280428-6b6e-5e08-a7a4-6aec7201ff44'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '9bbc0c2a-b339-5219-94c5-80da54ddf669'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'table', 'e → ie: lesen, sehen, fernsehen', 'e → ie: lesen, sehen, fernsehen', '{"type":"case_table","headers":["Person","lesen","sehen","fernsehen"],"rows":[["ich","lese","sehe","sehe fern"],["du","liest","siehst","siehst fern"],["er/sie/es","liest","sieht","sieht fern"],["wir","lesen","sehen","sehen fern"],["ihr","lest","seht","seht fern"],["sie/Sie","lesen","sehen","sehen fern"]],"highlight_row":-1,"description_de":"e wird zu ie bei du und er/sie/es. fernsehen ist trennbar: fern steht am Satzende.","description_en":"e becomes ie for du and er/sie/es. fernsehen is separable: fern goes to the end of the sentence."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
