INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '47fd9285-4ad8-5a8c-807c-767630672b87'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'table', 'a → ä: fahren, schlafen, tragen', 'a → ä: fahren, schlafen, tragen', '{"type":"case_table","headers":["Person","fahren","schlafen","tragen"],"rows":[["ich","fahre","schlafe","trage"],["du","fährst","schläfst","trägst"],["er/sie/es","fährt","schläft","trägt"],["wir","fahren","schlafen","tragen"],["ihr","fahrt","schlaft","tragt"],["sie/Sie","fahren","schlafen","tragen"]],"highlight_row":-1,"description_de":"a bekommt einen Umlaut (ä) bei du und er/sie/es.","description_en":"a takes an umlaut (ä) for du and er/sie/es."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '47fd9285-4ad8-5a8c-807c-767630672b87'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '0360d351-418e-511d-a8cb-e8164924a84e'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'tip', 'Only du and er/sie/es Change', 'Nur du und er/sie/es ändern sich', '{"content_de":"Der Vokalwechsel betrifft nur zwei Formen: du und er/sie/es. Ich, wir, ihr und sie/Sie bleiben immer regelmäßig.","content_en":"The vowel change affects only two forms: du and er/sie/es. ich, wir, ihr and sie/Sie always stay regular."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Only two forms change: du and er/sie/es. The other four stay regular.', 'Nur zwei Formen wechseln: du und er/sie/es. Die anderen vier bleiben regelmäßig.', NULL, NULL, 'wir sprechen and ihr sprecht never change — only du and er/sie/es do.', 'wir sprechen und ihr sprecht wechseln nie — nur du und er/sie/es.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '0360d351-418e-511d-a8cb-e8164924a84e'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1046a1ba-fc01-5150-bd33-a25c8e916ae1'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'list', 'All 15 Verbs by Change Type', 'Alle 15 Verben nach Wechseltyp', '{"type":"verb_list","groups":[{"category_en":"e → i","verbs":[{"de":"sprechen","en":"to speak (du sprichst)","example":"Sprichst du Deutsch?"},{"de":"essen","en":"to eat (du isst)","example":"Isst du gern Pizza?"},{"de":"geben","en":"to give (er gibt)","example":"Der Lehrer gibt Hausaufgaben."},{"de":"nehmen","en":"to take (du nimmst)","example":"Nimmst du den Bus?"},{"de":"helfen","en":"to help (du hilfst)","example":"Hilfst du gern?"},{"de":"treffen","en":"to meet (du triffst)","example":"Triffst du Anna?"}]},{"category_en":"e → ie","verbs":[{"de":"lesen","en":"to read (du liest)","example":"Liest du gern?"},{"de":"sehen","en":"to see (du siehst)","example":"Siehst du das?"},{"de":"fernsehen","en":"to watch TV (du siehst fern)","example":"Siehst du gern fern?"}]},{"category_en":"a → ä","verbs":[{"de":"fahren","en":"to drive/go (du fährst)","example":"Fährst du mit dem Bus?"},{"de":"schlafen","en":"to sleep (du schläfst)","example":"Schläfst du lange?"},{"de":"tragen","en":"to carry/wear (du trägst)","example":"Trägst du eine Jacke?"},{"de":"waschen","en":"to wash (du wäschst)","example":"Wäschst du das Auto?"},{"de":"anfangen","en":"to start (er fängt an)","example":"Er fängt um acht an."}]},{"category_en":"au → äu","verbs":[{"de":"laufen","en":"to run/walk (du läufst)","example":"Läufst du gern?"}]}],"description_en":"All 15 A1.2 stem-changing verbs, grouped by their vowel change.","description_de":"Alle 15 stammwechselnden Verben der A1.2, nach Vokalwechsel gruppiert."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1046a1ba-fc01-5150-bd33-a25c8e916ae1'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'eee8030c-cc80-545f-8ba7-7c13ccf1db61'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'warning', 'Common Mistakes', 'Häufige Fehler', '{"content_de":"Diese vier Fehler machen Lerner besonders oft.","content_en":"These four mistakes come up especially often."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"du fahrst","correct":"du fährst","explanation_de":"fahren wechselt a→ä bei du. Der Umlaut darf nicht fehlen.","explanation_en":"fahren changes a→ä for du. The umlaut cannot be left out."},{"wrong":"ihr spricht","correct":"ihr sprecht","explanation_de":"ihr wechselt den Vokal nie: sprecht bleibt regelmäßig.","explanation_en":"ihr never changes the vowel: sprecht stays regular."},{"wrong":"wir isst","correct":"wir essen","explanation_de":"wir wechselt den Vokal nie. Nur du und er/sie/es wechseln.","explanation_en":"wir never changes the vowel. Only du and er/sie/es change."},{"wrong":"du lesst","correct":"du liest","explanation_de":"Der Stamm von lesen endet auf -s. Darum kommt nur -t dazu: du liest — wie bei du heißt.","explanation_en":"The stem of lesen ends in -s. So only -t is added: du liest — like du heißt."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'eee8030c-cc80-545f-8ba7-7c13ccf1db61'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'f33cea48-f81b-5ed5-8401-c5a3988d24e5'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["15 Verben wechseln den Stammvokal, aber nur bei du und er/sie/es.","e → i: sprechen, essen, geben, nehmen, helfen, treffen.","e → ie: lesen, sehen, fernsehen.","a → ä: fahren, schlafen, tragen, waschen, anfangen.","au → äu: laufen (du läufst) — ein eigenes Muster.","ich, wir, ihr und sie/Sie bleiben immer regelmäßig.","nehmen verdoppelt zusätzlich das m: du nimmst, er nimmt.","Der du-Imperativ behält e→i/ie (Nimm!, Sprich!, Lies!), aber a→ä nicht (Fahr!)."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'f33cea48-f81b-5ed5-8401-c5a3988d24e5'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '40e48348-cb48-54b9-9b6b-f9428678e44d'::uuid, 'ba627722-82e9-5c38-a8f4-3b5913b7b4a4'::uuid, 'introduction', 'Imperative Introduction', 'Einführung: Imperativ', '{"hook_de":"Komm her! Mach das Fenster auf! Kommen Sie bitte! Das sind Bitten. Deutsch hat drei Formen.","hook_en":"Come here! Open the window! Please come! These are requests. German has three forms, one for each way of saying you: du, ihr and Sie.","scenario_en":"Use the imperative to ask someone to do something: open a window, pass an object, come on time.","preview_note_en":"Three ways to say Come! depending on who you are talking to.","preview_highlight":"Komm! Kommt! Kommen Sie!","why_it_matters_en":"You need the Sie-imperative for Sprechen Teil 3 of the exam: making polite requests from a picture card.","preview_example_de":"Komm! (du) Kommt! (ihr) Kommen Sie! (Sie)","preview_example_en":"Come! (to a friend) Come! (to friends) Come! (formal)","german_difference_en":"German drops the pronoun in the du- and ihr-imperative — Komm! not Du komm! English keeps you out of commands too (Come!), but German also changes the verb form, and some verbs change their vowel: Nimm! not Nehm!","english_comparison_en":"English has one command form: Come! German has three, because du, ihr and Sie are different people to address — and the Sie-form puts Sie right after the verb: Kommen Sie!"}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '40e48348-cb48-54b9-9b6b-f9428678e44d'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '9aa7a2d4-4918-5d62-ab02-edf4726ced12'::uuid, 'ba627722-82e9-5c38-a8f4-3b5913b7b4a4'::uuid, 'table', 'Imperative Forms: du, ihr, Sie', 'Imperativformen: du, ihr, Sie', '{"type":"case_table","headers":["Infinitiv","du","ihr","Sie (+ bitte)"],"rows":[["sein","Sei ruhig!","Seid ruhig!","Seien Sie ruhig!"],["haben","Hab keine Angst!","Habt keine Angst!","Haben Sie keine Angst!"],["kommen","Komm!","Kommt!","Kommen Sie!"],["machen","Mach!","Macht!","Machen Sie!"],["nehmen","Nimm!","Nehmt!","Nehmen Sie!"],["sprechen","Sprich!","Sprecht!","Sprechen Sie!"],["lesen","Lies!","Lest!","Lesen Sie!"],["essen","Iss!","Esst!","Essen Sie!"],["fahren","Fahr!","Fahrt!","Fahren Sie!"],["warten","Warte!","Wartet!","Warten Sie!"],["aufmachen","Mach das Fenster auf!","Macht das Fenster auf!","Machen Sie das Fenster auf!"]],"highlight_row":-1,"description_de":"sein und haben sind unregelmäßig. e→i/ie-Verben behalten den Vokalwechsel im du-Imperativ: Nimm!, Sprich!, Lies!, Iss! Trennbare Verben stellen das Präfix ans Ende.","description_en":"sein and haben are irregular. e→i/ie verbs keep the vowel change in the du-imperative: Nimm!, Sprich!, Lies!, Iss! Separable verbs send the prefix to the end."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'du: verb only, no ending, no du. ihr: same as normal ihr-form. Sie: infinitive + Sie, verb first.', 'du: nur das Verb, keine Endung, kein du. ihr: wie die normale ihr-Form. Sie: Infinitiv + Sie, Verb zuerst.', NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '9aa7a2d4-4918-5d62-ab02-edf4726ced12'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '53da8dd3-1623-5cb5-9b38-e988a78b8062'::uuid, 'ba627722-82e9-5c38-a8f4-3b5913b7b4a4'::uuid, 'pattern', 'How to Build the du-Imperative', 'So bildest du den du-Imperativ', '{"type":"steps","steps":[{"step":1,"title_de":"Nimm die du-Form des Verbs.","title_en":"Take the du-form of the verb.","detail_de":"du kommst, du sprichst, du fährst, du machst.","detail_en":"Start from the normal present-tense du-form: du kommst, du sprichst, du fährst, du machst."},{"step":2,"title_de":"Streiche du und die Endung -st.","title_en":"Drop du and the -st ending.","detail_de":"du komm(st) → Komm! du sprich(st) → Sprich! du mach(st) → Mach!","detail_en":"Remove the pronoun du and the -st ending, then add an exclamation mark: du komm(st) → Komm! du sprich(st) → Sprich!"},{"step":3,"title_de":"e→i/ie bleibt, a→ä wird wieder a.","title_en":"e→i/ie stays, a→ä goes back to a.","detail_de":"du sprichst → Sprich! (bleibt). Aber: du fährst → Fahr! (nicht Fähr!), du schläfst → Schlaf!","detail_en":"Verbs with e→i/ie keep the change: du sprichst → Sprich! But a→ä loses the umlaut again: du fährst → Fahr! (not Fähr!), du schläfst → Schlaf!"},{"step":4,"title_de":"Stamm auf -t/-d oder Konsonant+m/n? Dann kommt ein -e dazu.","title_en":"Stem ends in -t/-d or consonant+m/n? Add an -e.","detail_de":"du wartest → Warte! (nicht Wart!), du öffnest → Öffne! Aber: du wohnst → Wohn!, du lernst → Lern!","detail_en":"du wartest → Warte! (not Wart!), du öffnest → Öffne! But: du wohnst → Wohn!, du lernst → Lern! (vowel/l/r before -st needs no -e)."}],"description_en":"Four steps, always in the same order: du-form, drop du and -st, check the vowel, check the ending.","description_de":"Vier Schritte, immer in der gleichen Reihenfolge. du-Form, du und -st streichen, Vokal prüfen, Endung prüfen."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '53da8dd3-1623-5cb5-9b38-e988a78b8062'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'f7b3e47d-946a-58c1-a8b1-b90471be19fd'::uuid, 'ba627722-82e9-5c38-a8f4-3b5913b7b4a4'::uuid, 'tip', 'bitte and Politeness', 'bitte und Höflichkeit', '{"content_de":"bitte macht eine Bitte höflich. bitte steht meistens nach dem Verb oder am Ende. Komm bitte! Mach bitte die Tür zu. Ist die Person fremd? Dann nimm die Sie-Form. Machen Sie bitte das Fenster zu.","content_en":"bitte (please) makes a request polite. It usually stands right after the verb or at the end: Komm bitte! Mach bitte die Tür zu. Is the person a stranger? Then use the Sie-form: Machen Sie bitte das Fenster zu."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'In Sprechen Teil 3 the Sie-form with bitte is the safe choice.', 'In der Prüfung (Sprechen Teil 3) ist die Sie-Form mit bitte richtig.', NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'f7b3e47d-946a-58c1-a8b1-b90471be19fd'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '164cc176-ed16-5eaa-a708-6dce337e081a'::uuid, 'ba627722-82e9-5c38-a8f4-3b5913b7b4a4'::uuid, 'list', 'Requests in the Exam (Sprechen Teil 3)', 'Bitten in der Prüfung (Sprechen Teil 3)', '{"type":"verb_list","groups":[{"category_en":"Sprechen Teil 3: Bitten mit Bildkarten","verbs":[{"de":"Machen Sie bitte das Fenster zu.","en":"Please close the window.","example":"Bildkarte: Fenster (zu)"},{"de":"Machen Sie bitte die Tür auf.","en":"Please open the door.","example":"Bildkarte: Tür (auf)"},{"de":"Geben Sie bitte den Kuli.","en":"Please give the pen.","example":"Bildkarte: Kuli"},{"de":"Nehmen Sie bitte Platz.","en":"Please have a seat.","example":"Bildkarte: Stuhl"},{"de":"Kommen Sie bitte um drei Uhr.","en":"Please come at three o''clock.","example":"Bildkarte: Uhr"},{"de":"Warten Sie bitte einen Moment.","en":"Please wait a moment.","example":"Bildkarte: Wartezimmer"}]}],"description_en":"Six typical exam requests, all in the polite Sie-form with bitte.","description_de":"Sechs typische Prüfungsbitten, alle in der höflichen Sie-Form mit bitte."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Hören Teil 3 also uses the Sie-imperative, as in Bitte kommen Sie pünktlich.', 'Auch Hören Teil 3 benutzt den Sie-Imperativ. Beispiel: Bitte kommen Sie pünktlich.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '164cc176-ed16-5eaa-a708-6dce337e081a'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '13e05196-fd17-5a85-a753-dc4291369eb3'::uuid, 'ba627722-82e9-5c38-a8f4-3b5913b7b4a4'::uuid, 'warning', 'Common Mistakes', 'Häufige Fehler', '{"content_de":"Diese vier Fehler machen Lerner besonders oft.","content_en":"These four mistakes come up especially often."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Kommst du!","correct":"Komm!","explanation_de":"Der Imperativ hat kein du und keine Endung -st. Kommst du? ist eine Frage, kein Befehl.","explanation_en":"The imperative has no du and no -st ending. Kommst du? is a question, not a command."},{"wrong":"Fähr!","correct":"Fahr!","explanation_de":"a→ä-Verben verlieren den Umlaut im Imperativ wieder: du fährst, aber Fahr!","explanation_en":"a→ä verbs lose the umlaut again in the imperative: du fährst, but Fahr!"},{"wrong":"Bist ruhig!","correct":"Sei ruhig!","explanation_de":"sein ist unregelmäßig: der Imperativ heißt Sei!, nicht Bist!","explanation_en":"sein is irregular: the imperative is Sei!, not Bist!"},{"wrong":"Aufmach das Fenster!","correct":"Mach das Fenster auf!","explanation_de":"Trennbare Verben stellen das Präfix (auf) ans Ende, nicht davor.","explanation_en":"With separable verbs, the prefix (auf) goes to the end of the sentence, not before the verb."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '13e05196-fd17-5a85-a753-dc4291369eb3'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ccf7dddf-2662-5113-abfa-6b3be37f8fe2'::uuid, 'ba627722-82e9-5c38-a8f4-3b5913b7b4a4'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["du-Imperativ: du-Form ohne du und ohne -st. Komm! Mach! Sprich!","e→i/ie bleibt im du-Imperativ: Nimm!, Sprich!, Lies!, Iss!","a→ä verliert den Umlaut wieder: Fahr!, nicht Fähr!","Stämme auf -t/-d oder Konsonant+m/n behalten ein -e: Warte! Öffne!","ihr-Imperativ = die normale ihr-Form ohne ihr: Kommt! Lest! Seid!","Sie-Imperativ = Infinitiv + Sie, Verb zuerst: Kommen Sie! Machen Sie!","sein ist unregelmäßig: Sei! Seid! Seien Sie!","bitte macht die Bitte höflich; in der Prüfung: Sie-Form.","Trennbare Verben: das Präfix steht am Ende — Mach das Fenster auf!"]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ccf7dddf-2662-5113-abfa-6b3be37f8fe2'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'e7f05a3a-f520-514f-814f-7a7ebf5a307a'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'introduction', 'Perfekt Introduction', 'Einführung: das Perfekt', '{"hook_de":"Was hast du gestern gemacht? Das Perfekt ist die Zeit für gestern.","hook_en":"What did you do yesterday? The Perfekt is the tense for yesterday.","scenario_en":"Use the Perfekt to say what happened: Ich habe ein Buch gelesen. (I read a book.)","preview_note_en":"The Perfekt has two parts: haben or sein (position 2), plus Partizip II at the end.","preview_highlight":"Ich habe gekauft. / Ich bin gegangen.","why_it_matters_en":"The Perfekt is exam material: Goethe A1 Schreiben Teil 2 (a Mitteilung), Sprechen Teil 1, and Hören Teil 1.","preview_example_de":"Ich habe Kaffee getrunken.","preview_example_en":"I drank coffee.","german_difference_en":"German uses two verbs together: haben/sein plus a Partizip II, like English ''have'' + past participle (I have bought). But the Partizip II goes to the very end of the sentence, not right after haben.","english_comparison_en":"English: I bought bread yesterday (one past-tense verb). German: Ich habe gestern Brot gekauft (haben + Partizip II at the end). The word order is the big difference."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'e7f05a3a-f520-514f-814f-7a7ebf5a307a'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'fef5bb00-5cd3-5037-890c-cf47775838f8'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'pattern', 'The Sentence Bracket: haben/sein + Partizip II', 'Die Satzklammer: haben/sein + Partizip II', '{"type":"steps","steps":[{"step":1,"title_de":"haben oder sein auf Position 2.","title_en":"haben or sein goes in position 2.","detail_de":"Konjugiere haben oder sein wie im Präsens: ich habe / ich bin.","detail_en":"Conjugate haben or sein like in the present tense: ich habe, du hast, er hat... / ich bin, du bist, er ist... This is the only conjugated verb in the sentence."},{"step":2,"title_de":"Das Partizip II ist immer gleich.","title_en":"The Partizip II never changes.","detail_de":"gekauft, gegangen, gemacht: eine Form für jede Person.","detail_en":"gekauft, gegangen, gemacht... The Partizip II has one fixed form, the same for every person (ich, du, er...)."},{"step":3,"title_de":"Das Partizip II steht ganz am Ende.","title_en":"The Partizip II goes at the very end.","detail_de":"haben/sein zuerst, dann der Rest, dann das Partizip II. Das ist die Satzklammer.","detail_en":"haben/sein (position 2) ... the rest of the sentence ... Partizip II (end). This frame is called the Satzklammer, the sentence bracket."}],"description_en":"Two verb parts frame the sentence: the conjugated haben/sein in position 2, the fixed Partizip II at the end.","description_de":"Zwei Verbteile bilden einen Rahmen. haben/sein steht auf Position 2, das Partizip II am Ende."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'haben/sein opens the bracket, Partizip II closes it — everything else goes in the middle.', 'haben/sein öffnet die Klammer. Das Partizip II schließt sie. Alles andere kommt in die Mitte.', NULL, NULL, 'In a question, haben/sein moves to position 1 (Hast du...?) but the Partizip II still stays at the end.', 'In einer Frage steht haben/sein zuerst. Das Partizip II bleibt trotzdem am Ende.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'fef5bb00-5cd3-5037-890c-cf47775838f8'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '831f5db2-3cce-5be6-8742-48a4f58267ae'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'table', 'Regular Partizipien: ge-...-t', 'Regelmäßige Partizipien: ge-…-t', '{"type":"case_table","headers":["Infinitiv","Partizip II","Beispiel"],"rows":[["machen","gemacht","Ich habe die Hausaufgaben gemacht."],["kaufen","gekauft","Sie hat ein Kleid gekauft."],["kochen","gekocht","Wir haben Suppe gekocht."],["spielen","gespielt","Die Kinder haben Fußball gespielt."],["lernen","gelernt","Ich habe Deutsch gelernt."],["arbeiten","gearbeitet","Er hat viel gearbeitet."],["wohnen","gewohnt","Wir haben in Köln gewohnt."],["hören","gehört","Hast du die Musik gehört?"],["fragen","gefragt","Ich habe den Lehrer gefragt."],["sagen","gesagt","Was hast du gesagt?"],["telefonieren","telefoniert","Ich habe lange telefoniert."],["studieren","studiert","Sie hat in Berlin studiert."]],"highlight_row":-1,"description_de":"Regelmäßige Verben bilden das Partizip II mit ge- und -t. Verben auf -ieren bekommen kein ge-: telefoniert, studiert.","description_en":"Regular verbs form the Partizip II with ge- at the start and -t at the end. Verbs ending in -ieren drop the ge-: telefoniert, studiert."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Er hat gearbeiten.","correct":"Er hat gearbeitet.","explanation_de":"arbeiten braucht ein extra e vor -t. Also gearbeitet, nicht gearbeiten.","explanation_en":"arbeiten needs an extra e before -t: gearbeitet, not gearbeiten."},{"wrong":"Ich habe getelefoniert.","correct":"Ich habe telefoniert.","explanation_de":"Verben auf -ieren bekommen kein ge-. Also telefoniert, nicht getelefoniert.","explanation_en":"Verbs ending in -ieren never take ge-: telefoniert, not getelefoniert."}]'::jsonb, 'Regular verb → ge- + stem + -t. Verb ends in -ieren? Skip the ge- completely.', 'Regelmäßiges Verb → ge- + Stamm + -t. Verb endet auf -ieren? Kein ge-.', NULL, NULL, 'telefonieren and studieren are common exceptions to know by sound: no ge-, even though they end in -t like a regular Partizip.', 'telefonieren und studieren sind Ausnahmen: kein ge-. Sie enden trotzdem auf -t.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '831f5db2-3cce-5be6-8742-48a4f58267ae'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'c4ec177c-66b2-56ba-ba96-62ad62600be9'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'table', 'Irregular Partizipien: ge-...-en', 'Unregelmäßige Partizipien: ge-…-en', '{"type":"case_table","headers":["Infinitiv","Partizip II","haben/sein","Beispiel"],"rows":[["essen","gegessen","haben","Ich habe Pizza gegessen."],["trinken","getrunken","haben","Er hat Tee getrunken."],["sehen","gesehen","haben","Wir haben einen Film gesehen."],["lesen","gelesen","haben","Sie hat die Zeitung gelesen."],["schreiben","geschrieben","haben","Ich habe eine E-Mail geschrieben."],["sprechen","gesprochen","haben","Habt ihr Deutsch gesprochen?"],["nehmen","genommen","haben","Er hat den Bus genommen."],["finden","gefunden","haben","Ich habe meinen Schlüssel gefunden."],["schlafen","geschlafen","haben","Das Kind hat lange geschlafen."],["gehen","gegangen","sein","Wir sind nach Hause gegangen."],["fahren","gefahren","sein","Er ist nach Berlin gefahren."],["kommen","gekommen","sein","Sie ist um 8 Uhr gekommen."],["fliegen","geflogen","sein","Ich bin nach München geflogen."],["bleiben","geblieben","sein","Wir sind zu Hause geblieben."],["sein","gewesen","sein","Ich bin in Ankara gewesen."]],"highlight_row":-1,"description_de":"Unregelmäßige Verben haben ge- am Anfang und -en am Ende. Manche ändern den Vokal: nehmen → genommen.","description_en":"Irregular verbs form the Partizip II with ge- at the start and -en at the end — and some change their stem vowel (nehmen → genommen)."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich habe gegangen.","correct":"Ich bin gegangen.","explanation_de":"gehen ist ein Bewegungsverb. Perfekt mit sein, nicht mit haben.","explanation_en":"gehen is a verb of movement → its Perfekt uses sein, not haben."}]'::jsonb, 'Irregular verb → ge- + changed stem + -en. Learn each Partizip II by heart, like a vocabulary word.', 'Unregelmäßig: ge- + neuer Vokal + -en. Lerne jede Form wie ein Vokabelwort.', NULL, NULL, 'This table already shows haben or sein for each verb — the next rule explains the pattern behind it. sein still applies for the verb sein itself: war is more common than ist gewesen.', 'Diese Tabelle zeigt haben oder sein für jedes Verb. Regel 4 erklärt das Muster. Für sein sagt man meistens war. Siehe Regel 6.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'c4ec177c-66b2-56ba-ba96-62ad62600be9'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ad233412-8792-5dec-bf2d-d497ff43bcab'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'table', 'haben or sein? Choosing the Right Auxiliary', 'haben oder sein? Das richtige Hilfsverb wählen', '{"type":"case_table","headers":["Verb","Bedeutung","Beispiel"],"rows":[["gehen","movement","Ich bin nach Hause gegangen."],["fahren","movement","Wir sind mit dem Zug gefahren."],["kommen","movement","Er ist spät gekommen."],["fliegen","movement","Sie ist nach Rom geflogen."],["aufstehen","movement","Ich bin um 7 Uhr aufgestanden."],["bleiben","no movement — exception","Wir sind zu Hause geblieben."],["sein","no movement — exception","Ich bin krank gewesen."]],"highlight_row":-1,"description_de":"sein steht für Bewegung: du gehst von A nach B. bleiben und sein haben keine Bewegung. Trotzdem benutzt du sein — das sind zwei Ausnahmen.","description_en":"sein is used for movement from one place to another (gehen, fahren, kommen, fliegen, aufstehen). bleiben and sein show no movement but still take sein — memorise them as two exceptions."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich habe geblieben.","correct":"Ich bin geblieben.","explanation_de":"bleiben zeigt keine Bewegung. Trotzdem ist es eine Ausnahme: immer sein.","explanation_en":"bleiben shows no movement, but it is an exception: its Perfekt always uses sein."}]'::jsonb, 'Movement → sein. Almost everything else → haben. bleiben and sein are the two exceptions to just memorise.', 'Bewegung → sein. Fast alles andere → haben. bleiben und sein sind die zwei Ausnahmen.', NULL, NULL, 'All the Perfekt verbs in this course use haben, except these seven: gehen, fahren, kommen, fliegen, aufstehen, bleiben, sein.', 'Fast alle Perfekt-Verben in diesem Kurs benutzen haben. Diese sieben brauchen sein: gehen, fahren, kommen, fliegen, aufstehen, bleiben, sein.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ad233412-8792-5dec-bf2d-d497ff43bcab'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '05bc754b-61f6-5e1e-a331-9e27dc63383e'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'table', 'Separable Verbs in the Perfekt: ge- in the Middle', 'Trennbare Verben im Perfekt: ge- in der Mitte', '{"type":"case_table","headers":["Infinitiv","Partizip II","haben/sein","Beispiel"],"rows":[["anrufen","angerufen","haben","Ich habe meine Mutter angerufen."],["einkaufen","eingekauft","haben","Wir haben heute eingekauft."],["aufstehen","aufgestanden","sein","Er ist früh aufgestanden."]],"highlight_row":-1,"description_de":"Bei trennbaren Verben steht ge- in der Mitte. Zum Beispiel: an-ge-rufen, ein-ge-kauft, auf-ge-standen.","description_en":"For separable verbs, ge- moves inside the word, between the prefix and the stem: an-ge-rufen, ein-ge-kauft, auf-ge-standen."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich habe geanrufen.","correct":"Ich habe angerufen.","explanation_de":"Das Präfix bleibt vorne. ge- kommt direkt danach: angerufen.","explanation_en":"The prefix stays at the front, ge- comes right after it: angerufen."}]'::jsonb, 'Prefix stays first, ge- slides in right after it: an-ge-rufen, ein-ge-kauft.', 'Präfix bleibt vorne, ge- rutscht direkt danach: an-ge-rufen, ein-ge-kauft.', NULL, NULL, 'Unlike in the present tense, a separable verb''s Partizip II is one single word — it does not split across the sentence.', 'Das Partizip II ist immer ein Wort. Im Präsens ist das Verb getrennt: Ich rufe an.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '05bc754b-61f6-5e1e-a331-9e27dc63383e'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '5ddd57a9-8ed9-583a-9b5d-fc6c1e37a18a'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'table', 'war and hatte: the two Präteritum forms for yesterday', 'war und hatte: die zwei Formen für gestern', '{"type":"case_table","headers":["Person","sein → war","haben → hatte"],"rows":[["ich","war","hatte"],["du","warst","hattest"],["er/sie/es","war","hatte"],["wir","waren","hatten"],["ihr","wart","hattet"],["sie/Sie","waren","hatten"]],"highlight_row":-1,"description_de":"Für sein und haben nimmst du fast immer war/hatte. Kein Perfekt.","description_en":"For sein and haben, German almost always uses war/hatte instead of the Perfekt: Ich war müde. (I was tired.) Ich hatte keine Zeit. (I had no time.)"}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich bin gewesen müde.","correct":"Ich war müde.","explanation_de":"Für sein benutzt man war, nicht das Perfekt.","explanation_en":"For a simple ''I was tired'' sentence, German uses war — not the Perfekt ist gewesen."},{"wrong":"Ich hatte Hunger gehabt.","correct":"Ich hatte Hunger.","explanation_de":"hatte ist schon Vergangenheit. Kein Partizip II dazu.","explanation_en":"hatte is already past tense on its own — it never combines with a Partizip II like gehabt."}]'::jsonb, 'war and hatte are already past tense on their own — no haben/sein and no Partizip II needed with them.', 'war und hatte brauchen kein haben/sein. Kein Partizip II nötig.', NULL, NULL, 'ist gewesen and ich habe gehabt (the Perfekt forms) do exist and are correct, but war and hatte are far more common in everyday speech.', 'ist gewesen und hat gehabt gibt es auch. Aber im Alltag sagt man meistens war und hatte.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '5ddd57a9-8ed9-583a-9b5d-fc6c1e37a18a'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '490c38cc-6611-53e5-a1b6-32fa52d3ad61'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'warning', 'Four Mistakes in the Perfekt', 'Vier Fehler im Perfekt', '{"content_de":"Das Perfekt hat klare Regeln. Vier Fehler kommen oft.","content_en":"The Perfekt has clear rules, but four mistakes happen often: the wrong auxiliary, the wrong word order, a wrong Partizip II, and a missing or extra ge-."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich habe gegangen nach Hause.","correct":"Ich bin nach Hause gegangen.","explanation_de":"gehen braucht sein. Das Partizip steht am Ende.","explanation_en":"gehen needs sein (it''s a movement verb), and the Partizip II goes at the end of the sentence, not right after the auxiliary."},{"wrong":"Ich habe gekauft ein Brot.","correct":"Ich habe ein Brot gekauft.","explanation_de":"Das Objekt steht in der Mitte. Das Partizip bleibt am Ende.","explanation_en":"The object (ein Brot) sits inside the sentence bracket, and the Partizip II stays at the very end."},{"wrong":"Ich habe gearbeiten.","correct":"Ich habe gearbeitet.","explanation_de":"arbeiten braucht ein extra e vor -t. Also gearbeitet, nicht gearbeiten.","explanation_en":"arbeiten needs the extra e before -t: gearbeitet, not gearbeiten."},{"wrong":"Ich bin gewohnt in Köln.","correct":"Ich habe in Köln gewohnt.","explanation_de":"wohnen ist keine Bewegung. Perfekt mit haben, nicht sein.","explanation_en":"wohnen is not movement from one place to another → its Perfekt uses haben, not sein."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '490c38cc-6611-53e5-a1b6-32fa52d3ad61'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'dd0059c2-dea5-56c6-8593-b4f764dd92f8'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["The Perfekt = haben/sein (position 2) + Partizip II (end of sentence) — the Satzklammer.","Regular verbs: ge- + stem + -t (gekauft). Verbs on -ieren skip the ge-: telefoniert, studiert.","Irregular verbs: ge- + changed stem + -en (gegangen, genommen) — learn each one by heart.","sein is used for movement (gehen, fahren, kommen, fliegen, aufstehen) plus two exceptions: bleiben and sein.","Separable verbs put ge- in the middle: an-ge-rufen, ein-ge-kauft, auf-ge-standen.","For sein and haben themselves, use war/hatte instead of the Perfekt: Ich war müde. Ich hatte Zeit."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'dd0059c2-dea5-56c6-8593-b4f764dd92f8'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '54e269cc-69b7-59fc-b6e8-0f1733cb249b'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 'introduction', 'Dative Prepositions Introduction', 'Einführung: Präpositionen mit Dativ', '{"hook_de":"Du kennst für, ohne, gegen, um, durch mit Akkusativ. Jetzt lernst du sieben Präpositionen mit Dativ.","hook_en":"You know für, ohne, gegen, um, durch with Akkusativ. Now meet seven prepositions that always take the Dativ.","scenario_en":"Use these prepositions to say where you come from, where you live, and how you travel: Ich komme aus der Türkei. Ich fahre mit dem Bus.","preview_note_en":"aus, bei, mit, nach, von, zu, seit always take Dativ — the noun''s article changes: der → dem/der, ein → einem/einer.","preview_highlight":"aus, bei, mit, nach, von, zu, seit + Dativ","why_it_matters_en":"You need these prepositions for the Sprechen exam (Ich komme aus..., Ich wohne bei..., seit zwei Jahren) and for everyday directions (zum Bahnhof, zur Post).","preview_example_de":"Ich komme aus Deutschland. Ich fahre mit dem Bus.","preview_example_en":"I come from Germany. I go by bus.","german_difference_en":"In English, prepositions don''t change the words after them. In German, these seven prepositions always trigger Dativ: der becomes dem, die becomes der, and so on.","english_comparison_en":"English: from Germany, with the bus (no change). German: aus Deutschland, mit dem Bus — the article dem shows the Dativ case."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '54e269cc-69b7-59fc-b6e8-0f1733cb249b'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'bf85e826-7a40-50b7-a833-bce16266283b'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 'table', 'Dative Articles: der/die/das and ein/mein', 'Dativartikel: der/die/das und ein/mein', '{"type":"case_table","headers":["Nominativ","Dativ","Beispiel"],"rows":[["der (maskulin)","dem","mit dem Bruder"],["die (feminin)","der","mit der Schwester"],["das (neutral)","dem","mit dem Kind"],["die (Plural)","den + -n","mit den Kindern"],["ein (mask./neutr.)","einem","bei einem Freund"],["eine (feminin)","einer","bei einer Freundin"],["mein (mask./neutr.)","meinem","von meinem Vater"],["meine (feminin)","meiner","von meiner Mutter"],["meine (Plural)","meinen + -n","bei meinen Eltern"]],"highlight_row":-1,"description_de":"Im Dativ wird der/das zu dem, die zu der. Im Plural bekommt das Nomen ein -n: die Kinder → den Kindern.","description_en":"In the Dativ, der/das becomes dem and die becomes der. Plural nouns also add -n: die Kinder → den Kindern. ein-words (ein, mein...) take the same endings: -em (masc./neuter), -er (feminine), plural -en + noun -n."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"mit die Schwester","correct":"mit der Schwester","explanation_de":"mit braucht Dativ. die wird zu der.","explanation_en":"mit takes Dativ: die becomes der."},{"wrong":"mit den Kinder","correct":"mit den Kindern","explanation_de":"Im Dativ Plural bekommt das Nomen ein -n: Kinder → Kindern.","explanation_en":"In the Dativ plural, the noun itself adds an extra -n: Kinder → Kindern."}]'::jsonb, 'der/das → dem, die → der, plural noun → add -n. ein-words copy the same endings: -em, -er.', 'der/das → dem, die → der, Plural-Nomen → +n. ein-Wörter: -em, -er, -en.', NULL, NULL, 'dem and einem look similar (both masculine/neuter Dativ) — the -em ending is the pattern to remember, not the exact word.', 'dem und einem enden beide auf -em. Merke dir die Endung, nicht das Wort.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'bf85e826-7a40-50b7-a833-bce16266283b'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '9a58f166-5968-5ee6-bce0-668d461337f6'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 'table', 'The Seven Dative Prepositions', 'Die sieben Präpositionen mit Dativ', '{"type":"case_table","headers":["Präposition","Bedeutung","Beispiel"],"rows":[["aus","origin / from","Ich komme aus der Türkei."],["bei","at / with (a person, an employer)","Ich wohne bei meiner Oma. Ich arbeite bei der Post."],["mit","with / by (transport)","Ich fahre mit dem Bus."],["nach","to (a city/country)","Wir fahren nach Hamburg."],["von","from / of","Der Brief ist von meinem Freund."],["zu","to (a person/place)","Ich gehe zu meinem Arzt."],["seit","since / for (a time period)","Ich wohne seit zwei Jahren hier."]],"highlight_row":-1,"description_de":"Diese sieben Präpositionen stehen immer mit Dativ.","description_en":"These seven prepositions always take the Dativ — no matter what follows them."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"mit den Bus","correct":"mit dem Bus","explanation_de":"mit + Dativ: der Bus → dem Bus, nicht den (das ist Akkusativ).","explanation_en":"mit + Dativ: der Bus → dem Bus, not den (that is Akkusativ)."}]'::jsonb, 'aus, bei, mit, nach, von, zu, seit — always Dativ, no exceptions.', 'aus, bei, mit, nach, von, zu, seit — immer Dativ.', NULL, NULL, 'Unlike für/ohne/gegen/um/durch (always Akkusativ), these seven always take Dativ — memorise the two short lists separately.', 'für/ohne/gegen/um/durch nehmen immer Akkusativ. Diese sieben nehmen immer Dativ.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '9a58f166-5968-5ee6-bce0-668d461337f6'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '02cda234-1971-5bc2-98f1-ce6652f12641'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 'table', 'Contractions: zum, zur, beim, vom', 'Kurzformen: zum, zur, beim, vom', '{"type":"case_table","headers":["Präposition + dem/der","Kurzform","Beispiel"],"rows":[["zu + dem","zum","Ich gehe zum Bahnhof."],["zu + der","zur","Ich gehe zur Post."],["bei + dem","beim","Ich bin beim Arzt."],["von + dem","vom","Ich komme vom Supermarkt."]],"highlight_row":-1,"description_de":"zu, bei und von bilden oft eine Kurzform mit dem/der. zu dem und zu der sind richtig, aber sehr formell.","description_en":"zu, bei and von often merge with dem/der into one word. zu dem / zu der is not wrong, but it is very formal."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich gehe zu der Bahnhof.","correct":"Ich gehe zum Bahnhof.","explanation_de":"der Bahnhof ist maskulin: zu + dem = zum.","explanation_en":"der Bahnhof is masculine: zu + dem = zum."}]'::jsonb, 'zum, zur, beim, vom. Only dem and der contract — the plural (den) has no short form.', 'zum, zur, beim, vom. Der Plural (den) hat keine Kurzform.', 'Only zu, bei and von contract this way. mit, nach, aus and seit are never shortened.', 'mit, nach, aus und seit haben keine Kurzform.', NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '02cda234-1971-5bc2-98f1-ce6652f12641'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'bfcfd065-2598-5bc3-83b1-a6b1ec3c20d6'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 'table', 'aus vs. von, and nach vs. zu', 'aus oder von, und nach oder zu', '{"type":"case_table","headers":["Präposition","Wann?","Beispiel"],"rows":[["aus","dein Land, deine Stadt","Ich komme aus Polen."],["von","eine Person, ein Ort","Ich komme von der Arbeit."],["nach","ein Land, eine Stadt, nach Hause","Ich fahre nach Hamburg. Ich fahre nach Hause."],["zu","eine Person, ein Ort","Ich gehe zu meiner Oma."]],"highlight_row":-1,"description_de":"aus zeigt deine Heimat. von zeigt den Startort. Beispiel: von der Arbeit. nach geht zu einem Land oder einer Stadt. zu geht zu einer Person.","description_en":"aus shows where you originally come from (aus Polen); von shows a starting point (von der Arbeit). nach is for a country, city, or nach Hause; zu is for a person or a place (not a country/city)."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich komme von Polen.","correct":"Ich komme aus Polen.","explanation_de":"Für die Heimat benutzt man aus, nicht von.","explanation_en":"For your country/city of origin, use aus, not von."},{"wrong":"Ich gehe zu Berlin.","correct":"Ich fahre nach Berlin.","explanation_de":"Für Länder und Städte benutzt man nach, nicht zu.","explanation_en":"For countries and cities, use nach, not zu."}]'::jsonb, 'aus = origin (a country/city). nach = direction (a country/city, or Hause). zu = direction (a person/place). von = a starting point.', 'aus = Heimat. nach = Richtung (Land, Stadt, Hause). zu = Richtung (Person, Ort). von = Startort.', NULL, NULL, 'nach Hause (going home, movement) and zu Hause (being at home, no movement) are two different frozen phrases — never mix them up.', 'nach Hause ist Bewegung. zu Hause ist keine Bewegung. Nicht verwechseln.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'bfcfd065-2598-5bc3-83b1-a6b1ec3c20d6'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '9bc3bd51-ca2a-526f-980a-84b26a50c26e'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 'tip', 'seit + Zeitraum: Present Tense, Not Perfekt', 'seit + Zeitraum: Präsens, nicht Perfekt', '{"content_de":"seit + Zeit: Es dauert noch jetzt. Beispiel: seit zwei Jahren, seit Montag. Bei seit bleibt das Verb im Präsens. Kein Perfekt: Ich wohne seit 2020 hier.","content_en":"seit says how long something has been going on: seit zwei Jahren (for two years), seit Montag (since Monday). The verb stays in the present tense: Ich wohne seit 2020 hier. (I have lived here since 2020 — NOT the Perfekt.)"}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich habe seit zwei Jahren hier gewohnt.","correct":"Ich wohne seit zwei Jahren hier.","explanation_de":"Bei seit bleibt das Verb im Präsens. Kein Perfekt.","explanation_en":"seit + present tense describes something that continues until now — no Perfekt is needed."},{"wrong":"seit zwei Jahre","correct":"seit zwei Jahren","explanation_de":"seit + Dativ: Jahre bekommt ein -n im Plural: Jahren.","explanation_en":"seit + Dativ: the plural noun Jahre adds -n in the Dativ: Jahren."}]'::jsonb, 'seit = still true now → present tense, not Perfekt.', 'seit = gilt noch jetzt. Präsens, nicht Perfekt.', NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '9bc3bd51-ca2a-526f-980a-84b26a50c26e'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'e8a62672-f746-526e-94ce-07fe15fa27b5'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 'table', 'Transport: mit dem Bus, mit der U-Bahn', 'mit dem Bus, mit der U-Bahn', '{"type":"case_table","headers":["Womit?","Genus","Beispiel"],"rows":[["der Bus","maskulin","Ich fahre mit dem Bus."],["der Zug","maskulin","Ich fahre mit dem Zug."],["das Auto","neutral","Ich fahre mit dem Auto."],["die U-Bahn","feminin","Ich fahre mit der U-Bahn."],["die Straßenbahn","feminin","Ich fahre mit der Straßenbahn."]],"highlight_row":-1,"description_de":"mit + Dativ zeigt das Verkehrsmittel: mit dem Bus. Das brauchst du im Sprechen-Teil.","description_en":"mit + Dativ is the fixed pattern for naming a means of transport — useful material for the Sprechen part of the exam."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich fahre mit die U-Bahn.","correct":"Ich fahre mit der U-Bahn.","explanation_de":"die U-Bahn ist feminin. Im Dativ: der, nicht die.","explanation_en":"die U-Bahn is feminine → in the Dativ it becomes der, not die."}]'::jsonb, 'der/das Verkehrsmittel → mit dem. die U-Bahn/Straßenbahn → mit der.', 'der/das → mit dem. die U-Bahn/Straßenbahn → mit der.', NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'e8a62672-f746-526e-94ce-07fe15fa27b5'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '210f9f73-f2b8-595a-a936-4f0a3306fcdb'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 'warning', 'Four Mistakes with Dative Prepositions', 'Vier Fehler mit Dativ-Präpositionen', '{"content_de":"Kennst du die Regeln? Dann sind die sieben Präpositionen einfach. Vier Fehler kommen oft.","content_en":"These seven prepositions are simple once you know the rules. Four mistakes happen most often: the wrong case, the wrong preposition, a forgotten plural ending, and mixing up nach Hause / zu Hause."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"mit den Bus","correct":"mit dem Bus","explanation_de":"mit braucht Dativ. der Bus → dem Bus, nicht den.","explanation_en":"mit takes Dativ: der Bus → dem Bus, not den (that is Akkusativ)."},{"wrong":"Ich bin nach Hause. / Ich gehe zu Hause.","correct":"Ich bin zu Hause. / Ich gehe nach Hause.","explanation_de":"zu Hause: keine Bewegung. nach Hause: Bewegung.","explanation_en":"zu Hause = being there (no movement). nach Hause = going there (movement)."},{"wrong":"aus die Türkei","correct":"aus der Türkei","explanation_de":"aus braucht Dativ. die Türkei → der Türkei.","explanation_en":"aus takes Dativ: die Türkei → der Türkei, not die."},{"wrong":"seit zwei Jahre","correct":"seit zwei Jahren","explanation_de":"seit + Dativ Plural: Jahre bekommt ein -n.","explanation_en":"seit + Dativ plural: the noun adds -n: Jahre → Jahren."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '210f9f73-f2b8-595a-a936-4f0a3306fcdb'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'fb7ad36a-1f84-5e9e-a884-151cd8bb2436'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["aus, bei, mit, nach, von, zu, seit always take Dativ: der/das → dem, die → der, plural noun + -n.","zu + dem = zum, zu + der = zur, bei + dem = beim, von + dem = vom — the normal spoken forms.","aus = origin (a country/city). von = a starting point. nach = direction (country/city/Hause). zu = direction (a person/place).","seit + Zeitraum uses the present tense, not the Perfekt: Ich wohne seit 2020 hier.","mit + Dativ names a means of transport: mit dem Bus/Zug/Auto, mit der U-Bahn/Straßenbahn.","nach Hause = going home (movement). zu Hause = being at home (no movement)."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'fb7ad36a-1f84-5e9e-a884-151cd8bb2436'::uuid);

-- Examples
INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '152c5c99-e021-5cc2-9ca8-c71bd467c82d'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'Sprichst du Englisch?', 'Do you speak English?', 'Sprichst', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'sprechen changes e→i for du.', 'sprechen wechselt e→i bei du.', '{"Sprichst":"speak (du-form)","du":"you (informal)","Englisch":"English"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '152c5c99-e021-5cc2-9ca8-c71bd467c82d'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '3ff16386-8b90-52a1-b2f7-8a00409869cf'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'Isst du gern Pizza?', 'Do you like eating pizza?', 'Isst', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'essen changes e→i for du.', 'essen wechselt e→i bei du.', '{"Isst":"eat (du-form)","du":"you (informal)","gern":"gladly / like to","Pizza":"pizza"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '3ff16386-8b90-52a1-b2f7-8a00409869cf'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
