INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4cc17bd1-ee0e-5aea-ba61-15dcbd366619'::uuid, 'd1d5e6a5-bb41-595e-aa90-f0f02e535925'::uuid, 'Sie sieht am Morgen fern.', 'She watches TV in the morning.', 'sieht', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'fernsehen is separable; sehen changes e→ie for sie (she).', 'fernsehen ist trennbar; sehen wechselt e→ie bei sie (Einzahl).', '{"Sie":"she","sieht":"sees/watches (sie-form)","am":"in the (fixed phrase: am Morgen)","fern":"separable prefix of fernsehen (to watch TV)","Morgen":"morning"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4cc17bd1-ee0e-5aea-ba61-15dcbd366619'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
