INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '906415e7-b92e-5e01-899c-e9630fcd5f23'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'Er ist spät aufgestanden.', 'He got up late.', 'ist ... aufgestanden', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'aufstehen is separable and a movement verb → sein, ge- in the middle.', 'aufstehen ist trennbar und Bewegung → sein.', '{"Er":"he","ist":"is (aux)","spät":"late","aufgestanden":"got up"}'::jsonb, 2, 'everyday'
