INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'c159da77-2977-51c0-bef7-5e47c37de5fa'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 'Ich bin in Berlin geblieben.', 'I stayed in Berlin.', 'bin ... geblieben', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'bleiben shows no movement, but it is an exception that still uses sein.', 'bleiben ist eine Ausnahme mit sein.', '{"Ich":"I","bin":"am (aux)","in Berlin":"in Berlin","geblieben":"stayed"}'::jsonb, 2, 'everyday'
