SELECT 'f60f142b-04cb-51c7-a42b-89871c0ab4dc'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 4, 'multiple_choice', 'Wir ___ zu Hause geblieben. (bleiben, Perfekt)', 'Choose haben or sein: We stayed at home. (bleiben, Perfekt)', '["sind","haben","hatte","ist"]'::jsonb, 'sind', NULL, 'bleiben is an exception that takes sein, even without movement; wir → sind.', 'bleiben ist eine Ausnahme mit sein. wir → sind.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only sind matches wir + sein for bleiben; haben is the wrong auxiliary, hatte/ist are the wrong verb or person.', 'Nur sind passt zu wir + sein. haben ist falsch, hatte/ist sind falsches Verb oder falsche Person.', NULL
