INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd234c239-46d8-51b0-9c3b-88fab0bdc306'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 4, 'fill_blank', 'Er hat lange ___. (telefonieren, Perfekt)', 'Fill in the Partizip II: He talked on the phone for a long time. (telefonieren, Perfekt)', NULL, 'telefoniert', '["telefoniert"]'::jsonb, 'telefonieren ends in -ieren → no ge-: telefoniert.', 'telefonieren endet auf -ieren → kein ge-: telefoniert.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, '-ieren verbs drop the ge-, so the Partizip II is just telefoniert.', 'Verben auf -ieren lassen das ge- weg: telefoniert.', NULL
