SELECT 'b2e95a73-37d8-5553-8ba5-7190f78fcd3f'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 4, 'fill_blank', 'Wir ___ keine Zeit. (haben, Präteritum, wir)', 'Fill in the Präteritum of haben for wir: We had no time.', NULL, 'hatten', '["hatten"]'::jsonb, 'For haben, German uses hatte(n) instead of the Perfekt.', 'Für haben benutzt man hatte(n), nicht das Perfekt.', NULL, 11, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'wir hatten is the only correct Präteritum form of haben for wir.', 'Nur hatten passt zu haben und wir.', NULL
