SELECT 'e15ab4cc-12c0-50e8-8e59-447896d1d452'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence has the correct Satzklammer (auxiliary in position 2, Partizip II at the end)?', '["Ich gesehen habe einen Film.","Ich habe einen Film gesehen.","Ich habe gesehen einen Film.","Habe gesehen ich einen Film."]'::jsonb, 'Ich habe einen Film gesehen.', NULL, 'haben in position 2, gesehen at the very end.', 'habe auf Position 2, gesehen ganz am Ende.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only this order keeps habe in position 2 and gesehen at the end; the others break the Satzklammer.', 'Nur diese Reihenfolge hat habe auf Position 2 und gesehen am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e15ab4cc-12c0-50e8-8e59-447896d1d452'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6868b16e-5eff-546f-8364-c13368d5b694'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 4, 'multiple_choice', 'Er ___ um 8 Uhr gekommen. (kommen, Perfekt, er)', 'Choose the correct auxiliary form: He arrived at 8 o''clock. (kommen, Perfekt)', '["hat","hatte","ist","seid"]'::jsonb, 'ist', NULL, 'kommen is a movement verb → sein; er → ist.', 'kommen ist Bewegung → sein. er → ist.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only ist matches er + sein; hat/hatte use the wrong auxiliary, seid is the wrong person.', 'Nur ist passt zu er + sein. hat/hatte sind falsches Hilfsverb, seid ist falsche Person.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6868b16e-5eff-546f-8364-c13368d5b694'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
