SELECT '279d7e13-7875-58ef-b396-ce7bca7f21f9'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 5, 'multiple_choice', 'Ich habe das Essen ___. (kochen, Perfekt)', 'Choose the correct Partizip II: I cooked the food. (kochen, Perfekt)', '["kocht","gekochen","gekochte","gekocht"]'::jsonb, 'gekocht', NULL, 'kochen is regular → ge- + koch + t = gekocht.', 'kochen ist regelmäßig → gekocht.', NULL, 10, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only gekocht follows the regular ge-...-t pattern; the others are not valid Partizip II forms.', 'Nur gekocht folgt dem Muster ge-…-t. Die anderen sind keine Partizip-II-Formen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '279d7e13-7875-58ef-b396-ce7bca7f21f9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8a5bcfc5-35b5-54ff-9f8d-ed44d8ce770e'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 5, 'multiple_choice', '___ ihr schon gegessen? (essen, Perfekt, ihr)', 'Choose the correct auxiliary for ihr: Have you (plural) already eaten? (essen, Perfekt)', '["Ist","Habt","Seid","Hat"]'::jsonb, 'Habt', NULL, 'essen uses haben; ihr → habt, moved to position 1 for the question.', 'essen benutzt haben. ihr → habt, an erster Stelle in der Frage.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only Habt matches ihr + haben; Seid/Ist use the wrong auxiliary, Hat is the wrong person.', 'Nur Habt passt zu ihr + haben. Seid/Ist sind falsches Hilfsverb, Hat ist falsche Person.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8a5bcfc5-35b5-54ff-9f8d-ed44d8ce770e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4f3c4cd5-b53e-545e-8771-bad46b9dc401'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 5, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence has the correct Satzklammer (auxiliary in position 2, Partizip II at the end)?', '["Er geschrieben hat einen Brief.","Hat geschrieben er einen Brief.","Er hat einen Brief geschrieben.","Er hat geschrieben einen Brief."]'::jsonb, 'Er hat einen Brief geschrieben.', NULL, 'haben in position 2, geschrieben at the very end.', 'hat auf Position 2, geschrieben ganz am Ende.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only this order keeps hat in position 2 and geschrieben at the end.', 'Nur diese Reihenfolge hat hat auf Position 2 und geschrieben am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4f3c4cd5-b53e-545e-8771-bad46b9dc401'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f395ecf6-81ba-5c61-b614-cb3ed529a391'::uuid, '86b1e4a7-5b83-5f9c-91db-a6c45cf13f61'::uuid, 5, 'sentence_building', 'Schreib den Satz im Perfekt: [ich / meine Freundin / anrufen]', 'Write the sentence in the Perfekt: I called my girlfriend. Start with ich. [ich / meine Freundin / anrufen]', NULL, 'Ich habe meine Freundin angerufen.', '["Ich habe meine Freundin angerufen"]'::jsonb, 'anrufen is separable → angerufen, with haben.', 'anrufen ist trennbar → angerufen, mit haben.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The cue puts ich first. habe follows in position 2, angerufen ends the sentence.', 'Die Vorgabe setzt ich zuerst. habe kommt auf Position 2, angerufen am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f395ecf6-81ba-5c61-b614-cb3ed529a391'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c411f711-2a22-5b8b-8688-5b1219f44600'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'fill_blank', 'Ich fahre mit ___ Bus. (der Bus, Dativ)', 'Fill in the Dativ article: I go by bus. (der Bus)', NULL, 'dem', '["dem"]'::jsonb, 'mit + Dativ: der Bus → dem Bus.', 'mit + Dativ: der Bus → dem Bus.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'der Bus is masculine, so its Dativ article is dem.', 'der Bus ist maskulin. Dativ: dem.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c411f711-2a22-5b8b-8688-5b1219f44600'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3b9c3151-8adb-5f9c-8c69-75242836943c'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'fill_blank', 'Ich fahre mit ___ U-Bahn. (die U-Bahn, Dativ)', 'Fill in the Dativ article: I go by subway. (die U-Bahn)', NULL, 'der', '["der"]'::jsonb, 'mit + Dativ: die U-Bahn → der U-Bahn.', 'mit + Dativ: die U-Bahn → der U-Bahn.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'die U-Bahn is feminine, so its Dativ article is der.', 'die U-Bahn ist feminin. Dativ: der.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3b9c3151-8adb-5f9c-8c69-75242836943c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b0d391e3-ff5b-5b59-9359-677af160e896'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'fill_blank', 'Ich komme aus ___ Türkei. (die Türkei, Dativ; aus hat keine Kurzform)', 'Fill in the Dativ article: I come from Turkey. (die Türkei)', NULL, 'der', '["der"]'::jsonb, 'aus + Dativ: die Türkei → der Türkei. aus never contracts.', 'aus + Dativ: die Türkei → der Türkei. aus hat keine Kurzform.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'die Türkei is feminine, so the Dativ article is der.', 'die Türkei ist feminin. Dativ: der.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b0d391e3-ff5b-5b59-9359-677af160e896'::uuid);

