SELECT '96034fda-42dc-5e3d-8c8d-3c7c82591baf'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'fill_blank', 'Ich gehe ___ Bahnhof. (zu + dem, Kurzform)', 'Fill in the contraction of zu + dem: I''m going to the train station.', NULL, 'zum', '["zum"]'::jsonb, 'zu + dem contracts to zum.', 'zu + dem wird zu zum.', NULL, 4, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'der Bahnhof is masculine, so zu + dem contracts to zum.', 'der Bahnhof ist maskulin. zu + dem = zum.', NULL
