SELECT '49d0d7b5-dbe0-560a-bce0-266b040e5851'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'fill_blank', 'Ich gehe ___ Post. (zu + der, Kurzform)', 'Fill in the contraction of zu + der: I''m going to the post office.', NULL, 'zur', '["zur"]'::jsonb, 'zu + der contracts to zur.', 'zu + der wird zu zur.', NULL, 5, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'die Post is feminine, so zu + der contracts to zur.', 'die Post ist feminin. zu + der = zur.', NULL
