SELECT 'ed269168-30a9-5096-855e-ee4a45232dd8'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'multiple_choice', 'Ich komme ___ Supermarkt. (von + dem, Kurzform)', 'Choose the contraction of von + dem: I''m coming from the supermarket.', '["vom","von der","zum","beim"]'::jsonb, 'vom', NULL, 'von + dem contracts to vom, the normal spoken form.', 'von + dem wird zu vom. So sagt man das meistens.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only vom is the contraction of von + dem; von der uses the wrong gender, zum/beim belong to different prepositions.', 'Nur vom passt zu von + dem. der Supermarkt ist maskulin, nicht feminin.', NULL
