SELECT '0ae744d6-6dc7-5d46-9f4c-9fe0bed9e859'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'fill_blank', 'Wir fahren mit ___. (die Kinder, Dativ Plural)', 'Fill in the full Dativ plural form (article + noun ending): We travel with the children. (die Kinder)', NULL, 'den Kindern', '["den Kindern"]'::jsonb, 'mit + Dativ Plural: die Kinder → den Kindern (article den, noun +n).', 'mit + Dativ Plural: die Kinder → den Kindern.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Plural article in the Dativ is always den, and the noun itself adds -n: Kindern.', 'Plural-Artikel im Dativ ist immer den. Das Nomen bekommt -n: Kindern.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0ae744d6-6dc7-5d46-9f4c-9fe0bed9e859'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e5acc456-1953-5d55-a147-3b59b516a2e0'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'fill_blank', 'Ich wohne seit zwei ___. (Jahr, Dativ Plural)', 'Fill in the Dativ plural of Jahr: I''ve lived here for two years.', NULL, 'Jahren', '["Jahren"]'::jsonb, 'seit + Dativ Plural: Jahre adds -n → Jahren.', 'seit + Dativ Plural: Jahre bekommt -n → Jahren.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Plural nouns in the Dativ always add -n, so Jahre becomes Jahren.', 'Plural-Nomen bekommen im Dativ -n. Jahre wird Jahren.', NULL
