INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'aa5d74f8-d18d-5156-bf81-2e0dceb66b8e'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'multiple_choice', 'Ich ___ heute zu Hause. (sein, keine Bewegung)', 'Choose the right verb form: I am at home today. (no movement)', '["gehe","bin","fahre","komme"]'::jsonb, 'bin', NULL, 'zu Hause = being there, no movement, so sein (bin) is correct.', 'zu Hause: keine Bewegung. Also sein (bin).', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'zu Hause describes a state, not a movement, so it needs bin, not a movement verb.', 'zu Hause ist ein Zustand, keine Bewegung. Also bin.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'aa5d74f8-d18d-5156-bf81-2e0dceb66b8e'::uuid);

