SELECT 'a7a85f73-b356-5856-b5db-f2b9a744a501'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'multiple_choice', 'Morgen fahre ich ___. (Bewegung, nach Hause / zu Hause)', 'Choose the correct phrase: Tomorrow I''m going home. (movement)', '["zu Hause","aus Hause","von Hause","nach Hause"]'::jsonb, 'nach Hause', NULL, 'nach Hause = going home, movement toward home.', 'nach Hause: Bewegung nach Hause.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'fahren describes movement, so the phrase must be nach Hause, not zu Hause.', 'fahren ist Bewegung. Also nach Hause, nicht zu Hause.', NULL
