SELECT 'fe97d1bc-1569-5fa8-a988-5ab810e33a1c'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 4, 'fill_blank', 'Ich komme ___ der Arbeit. (Startort, kein Land)', 'Fill in the preposition for a starting point: I''m coming from work.', NULL, 'von', '["von"]'::jsonb, 'von marks a starting point like work, not a country of origin.', 'von zeigt den Startort, nicht die Heimat.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'von marks a place you leave. For your home country, use aus instead.', 'von zeigt den Startort. Für die Heimat nimmst du aus.', NULL
