INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8a22bb70-a298-5543-8474-7d2fc11c415f'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / mit / mein Bruder / sprechen]', 'Write the sentence: I''m talking with my brother. Start with ich. [ich / mit / mein Bruder / sprechen]', NULL, 'Ich spreche mit meinem Bruder.', '["Ich spreche mit meinem Bruder"]'::jsonb, 'mit + Dativ: mein Bruder → meinem Bruder (masculine).', 'mit + Dativ: mein Bruder → meinem Bruder.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The cue puts ich first. mein Bruder is masculine, so mit needs meinem.', 'Die Vorgabe setzt ich zuerst. mein Bruder ist maskulin, also meinem.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8a22bb70-a298-5543-8474-7d2fc11c415f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '9d8b2422-c4db-5bf0-9b72-cb7fa05a5e1e'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'sentence_building', 'Schreib den Satz mit einer Kurzform: [ich / gehen / zu / der Arzt]', 'Write the sentence using a contraction: I''m going to the doctor. Start with ich. [ich / gehen / zu / der Arzt]', NULL, 'Ich gehe zum Arzt.', '["Ich gehe zum Arzt"]'::jsonb, 'zu + dem (der Arzt is masculine) contracts to zum.', 'zu + dem (der Arzt ist maskulin) wird zu zum.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The cue puts ich first. der Arzt is masculine, so zu contracts to zum.', 'Die Vorgabe setzt ich zuerst. der Arzt ist maskulin, also zum.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '9d8b2422-c4db-5bf0-9b72-cb7fa05a5e1e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ee2c444a-6f1f-5166-85e7-a801dbcd5590'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / wohnen / bei / meine Eltern]', 'Write the sentence: I live with my parents. Start with ich. [ich / wohnen / bei / meine Eltern]', NULL, 'Ich wohne bei meinen Eltern.', '["Ich wohne bei meinen Eltern"]'::jsonb, 'bei + Dativ Plural: meine Eltern → meinen Eltern.', 'bei + Dativ Plural: meine Eltern → meinen Eltern.', NULL, 3, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The cue puts ich first. Eltern is plural, so meine becomes meinen.', 'Die Vorgabe setzt ich zuerst. Eltern ist Plural, also meinen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ee2c444a-6f1f-5166-85e7-a801dbcd5590'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8b2e5c13-dce3-5540-a8dc-6e37a389d300'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / arbeiten / bei / die Bank]', 'Write the sentence: I work at the bank. Start with ich. [ich / arbeiten / bei / die Bank]', NULL, 'Ich arbeite bei der Bank.', '["Ich arbeite bei der Bank"]'::jsonb, 'bei + Dativ names an employer: die Bank → der Bank.', 'bei + Dativ nennt einen Arbeitgeber: die Bank → der Bank.', NULL, 4, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'The cue puts ich first. die Bank is feminine, so bei needs der.', 'Die Vorgabe setzt ich zuerst. die Bank ist feminin, also der.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8b2e5c13-dce3-5540-a8dc-6e37a389d300'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b484df20-10dc-5a1d-ab9e-68374c0fce16'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'sentence_building', 'Schreib den Satz: [das Buch / sein / von / meine Mutter]', 'Write the sentence: The book is from my mother. Start with das Buch. [das Buch / sein / von / meine Mutter]', NULL, 'Das Buch ist von meiner Mutter.', '["Das Buch ist von meiner Mutter"]'::jsonb, 'von + Dativ: meine Mutter → meiner Mutter (feminine).', 'von + Dativ: meine Mutter → meiner Mutter.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The cue puts das Buch first. meine Mutter is feminine, so von needs meiner.', 'Die Vorgabe setzt das Buch zuerst. meine Mutter ist feminin, also meiner.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b484df20-10dc-5a1d-ab9e-68374c0fce16'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bed61150-dfde-548b-9198-52f6d513639f'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / wohnen / seit / drei Jahre / hier]', 'Write the sentence: I''ve lived here for three years. Start with ich. [ich / wohnen / seit / drei Jahre / hier]', NULL, 'Ich wohne seit drei Jahren hier.', '["Ich wohne seit drei Jahren hier"]'::jsonb, 'seit + Dativ Plural: drei Jahre → drei Jahren. Present tense, not Perfekt.', 'seit + Dativ Plural: drei Jahre → drei Jahren. Präsens, nicht Perfekt.', NULL, 6, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The cue puts ich first. Jahre must add -n after seit, and the verb stays present tense.', 'Die Vorgabe setzt ich zuerst. Jahre bekommt -n. Das Verb bleibt im Präsens.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bed61150-dfde-548b-9198-52f6d513639f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ac40a177-63e2-507e-b0e6-813eff156d19'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'sentence_building', 'Schreib den Satz: [der Brief / sein / von / mein Vater]', 'Write the sentence: The letter is from my father. Start with der Brief. [der Brief / sein / von / mein Vater]', NULL, 'Der Brief ist von meinem Vater.', '["Der Brief ist von meinem Vater"]'::jsonb, 'von + Dativ: mein Vater → meinem Vater (masculine).', 'von + Dativ: mein Vater → meinem Vater.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The cue puts der Brief first. mein Vater is masculine, so von needs meinem.', 'Die Vorgabe setzt der Brief zuerst. mein Vater ist maskulin, also meinem.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ac40a177-63e2-507e-b0e6-813eff156d19'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f7aa6e9b-0c37-5874-b2b0-2e311896881a'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'fill_blank', 'Ich bin ___ meiner Freundin. (bei + Dativ, volle Form)', 'Fill in bei — use the full form, not a contraction: I''m at my girlfriend''s. (bei + Dativ)', NULL, 'bei', '["bei"]'::jsonb, 'bei + Dativ (meiner Freundin) — a possessive can''t contract with bei, only dem/der do.', 'bei + Dativ (meiner Freundin). Nur dem/der bilden eine Kurzform.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The preposition itself is bei; only bei + dem contracts to beim, and meiner is not dem.', 'Die Präposition ist bei. Nur bei + dem wird zu beim.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f7aa6e9b-0c37-5874-b2b0-2e311896881a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'eec3bcc5-32be-5e44-915e-c9c810980456'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'fill_blank', 'Wir fahren ___ Deutschland. (Richtung, Land)', 'Fill in the preposition for direction: We''re traveling to Germany. (a country)', NULL, 'nach', '["nach"]'::jsonb, 'nach is used for direction toward a country or city.', 'nach benutzt man für die Richtung zu einem Land.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'For a country, nach is correct; zu is only for people or places, not countries.', 'Für ein Land ist nach richtig. zu gilt nur für Personen oder Orte.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'eec3bcc5-32be-5e44-915e-c9c810980456'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7227417e-2b9e-549e-bfcb-6932043bf3d2'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'multiple_choice', 'Ich gehe ___ meiner Oma. (Richtung, Person)', 'Choose the preposition for direction toward a person: I''m going to my grandma''s.', '["nach","zu","aus","von"]'::jsonb, 'zu', NULL, 'zu is used for direction toward a person or place, not a country.', 'zu benutzt man für die Richtung zu einer Person.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only zu fits direction toward a person; nach is for countries/cities, aus/von point the wrong way.', 'Nur zu passt zur Person. nach gilt für Länder oder Städte. aus/von passen hier nicht.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7227417e-2b9e-549e-bfcb-6932043bf3d2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '22617e7b-e0cc-5dd0-8aae-cb1d72e79d63'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct?', '["Ich fahre mit den Auto.","Ich fahre mit die Auto.","Ich fahre mit dem Auto.","Ich fahre mit einen Auto."]'::jsonb, 'Ich fahre mit dem Auto.', NULL, 'das Auto is neuter, so mit + Dativ gives dem Auto.', 'das Auto ist neutral. mit + Dativ: dem Auto.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only dem is the correct neuter Dativ article after mit; den/die/einen are wrong forms here.', 'Nur dem ist richtig hier. den/die/einen passen nicht.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '22617e7b-e0cc-5dd0-8aae-cb1d72e79d63'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '969b1a66-00b7-5a9a-97fa-254f9258c221'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'multiple_choice', 'Ich wohne seit einem ___. (Monat, Dativ)', 'Choose the correct Dativ form: I''ve lived here for a month. (Monat)', '["Monats","Monaten","Monat","Monate"]'::jsonb, 'Monat', NULL, 'einem Monat: masculine singular Dativ needs no extra ending on the noun (unlike the plural).', 'einem Monat: Singular im Dativ braucht keine extra Endung.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only the singular Dativ Monat is correct here; the other endings belong to the plural or other cases.', 'Nur der Singular-Dativ Monat ist hier richtig.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '969b1a66-00b7-5a9a-97fa-254f9258c221'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'daefa869-b788-53ac-be04-a5a450667426'::uuid, '5571e4b0-5858-5e86-abe1-473fe31cd874'::uuid, 5, 'sentence_building', 'Schreib den Satz mit einer Kurzform: [ich / sein / bei / der Zahnarzt]', 'Write the sentence using a contraction: I''m at the dentist''s. Start with ich. [ich / sein / bei / der Zahnarzt]', NULL, 'Ich bin beim Zahnarzt.', '["Ich bin beim Zahnarzt"]'::jsonb, 'bei + dem (der Zahnarzt is masculine) contracts to beim.', 'bei + dem (der Zahnarzt ist maskulin) wird zu beim.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The cue puts ich first. der Zahnarzt is masculine, so bei contracts to beim.', 'Die Vorgabe setzt ich zuerst. der Zahnarzt ist maskulin, also beim.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'daefa869-b788-53ac-be04-a5a450667426'::uuid);


COMMIT;

